                  }}
                >
                  Inscribirse
                </Button>
              ) : showPasswordInput ? (
                <div className="flex w-56 flex-col gap-2">
                  <PasswordInput
                    placeholder="Contraseña"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                  />

                  <Button
                    size="sm"
                    onClick={() => {
                      // TODO:
                      // llamar al endpoint enviando:
                      // contest.idConcurso
                      // password
                    }}
                  >
                    Acceder
                  </Button>
                </div>
              ) : (
                <Button size="sm" onClick={() => setShowPasswordInput(true)}>
                  Inscribirse
                </Button>
              ))}
          </div>
        </div> */}

        {/* <div className="space-y-2">
          <h2 className="text-lg font-semibold text-[var(--text-primary)]">
            {contest.nombre}
          </h2>

          <p className="text-sm text-[var(--text-secondary)]">
            {contest.descripcion}
          </p>
        </div> */}
        <div className="space-y-3">
          <div>
            <h2 className="text-lg font-semibold text-[var(--text-primary)]">
              {contest.nombre}
            </h2>

            <p className="text-sm text-[var(--text-secondary)]">
              {contest.descripcion}
            </p>
          </div>

          {/* {!contest.yaInscrito &&
            contest.estadoTiempo !== 'Finalizado' &&
            (contest.modalidad === 'Publico' ? (
              <Button
                className="w-full"
                onClick={() => {
                  // TODO:
                  // inscripción pública
                }}
              >
                Inscribirse
              </Button>
            ) : showPasswordInput ? (
              <div className="space-y-2">
                <PasswordInput
                  placeholder="Contraseña"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />

                <Button
                  className="w-full"
                  onClick={() => {
                    // TODO:
                    // inscripción privada
                  }}
                >
                  Acceder
                </Button>
              </div>
            ) : (
              <Button
                className="w-full"
                onClick={() => setShowPasswordInput(true)}
              >
                Inscribirse
              </Button>
            ))} */}

