            (contest.modalidad === 'Publico' ? (
              <Button
                className="w-full"
                onClick={() => {
                  // inscripción pública
                }}
              >
                Inscribirse
              </Button>
            ) : showPasswordInput ? (
              <div className="space-y-2">
                <PasswordInput
                  placeholder="Contraseña"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />

                <Button
                  className="w-full"
                  onClick={() => {
                    // inscripción privada
                  }}
                >
                  Acceder
                </Button>
              </div>
            ) : (
              <Button
                className="w-full"
                onClick={() => setShowPasswordInput(true)}
              >
                Inscribirse
              </Button>
            ))}
