              )}
            </div>
          )}

          {/* <ProgressBar
          className="mt-3"
          value={progress}
          label="Tiempo transcurrido"
        /> */}
          {/* {contest.estadoTiempo === 'Activo' && (
            <ProgressBar
              className="mt-3"
              value={progress}
              label="Tiempo transcurrido"
            />
          )} */}

          {contest.estadoTiempo === 'Activo' && (
